entries[223844] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nThis handheld device was used by star-augurs to focus immense amounts of starlight into a small, concentrated area. The device was mainly used during festivals, star-worship rituals, or when the augur needed to reach something on a high shelf." }
