entries[223846] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nThe ruling princes and princesses in Suramar chose only to wear their crowns at the most formal events. They were kept locked up at all other times, and were considered unstylish." }
entries[223847] = { ["name"] = "Charmed Withered Advanced" }
entries[223848] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nBlack Rook Hold was maintained and upkept by a small army of servants. One such servant was named Kalyndras, who was responsible for overseeing the Hold's armory and munitions storage. Like most of Ravencrest's servants, he fell to demons during the War of the Ancients." }
entries[223849] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nThis immensely powerful Highborne spell focus was shattered in a reckless archaeological expedition. Its shards are all that remain." }
entries[223850] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nThis key does not open any door. Rather, it is a ceremonial gesture of invitation to the Academy, as a way of saying, \"Our doors are open to you.\"" }
entries[223851] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nRevered by miners and blacksmiths, Rethu Ironhorn was one of the first tauren settlers in the Broken Isles. His descendants carry on his tradition of metalworking at Ironhorn Enclave, near the peak of Highmountain." }
entries[223852] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nThe drogbar have always been masters at jewelcrafting. In particular, tribal shaman would wear heavy, three-stoned necklaces. These necklaces were passed down from master to student." }
entries[223853] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nEche'ro was the pet, mount, and battle companion of Huln Highmountain, legendary hero of the War of the Ancients." }
entries[223854] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nThe eye of a powerful demon, preserved in the cold, stony ground of Stormheim. Writings from the time of the War of the Ancients state that Undravius was a fel lord commander with designs on removing all life from Azeroth." }
entries[223855] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nUnder the guidance of uncooperative mo'arg engineers, demon hunters were able to create several of these portals to Mardum. Unfortunately, they never quite caught on, as they usually let more demons out than in." }
entries[223856] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nMany a reckless adventurer has met her end by activating one of these devices without knowing its function. It is often unclear as to whether its activation will summon a single imp or a legion of pit lords." }
entries[223857] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nIt is unclear why any being - demonic or Azerothian - would choose to put themselves on Mannoroth's bad side by keeping some of his blood in a jar." }
entries[223858] = { ["name"] = "Archaeology Project", ["text"] = "Instant\nIn their haste, the draenei brought few artifacts with them as they left Argus. This book is one of the few relics that has survived the trip to this day." }
